function dump(node, depth) {
  if (depth > 2) return '';
  const pad = '  '.repeat(depth);
  let s = `${pad}${node.type} ${node.name} id=${node.id} x=${Math.round(node.x)} y=${Math.round(node.y)} w=${Math.round(node.width)} h=${Math.round(node.height)}`;
  if (node.type === 'TEXT') {
    s += ` chars=${JSON.stringify(node.characters)}`;
    try { s += ` font=${node.fontName.family}/${node.fontName.style} size=${node.fontSize}`; } catch(e){}
  }
  if (node.fills) {
    s += ` fill=${JSON.stringify(node.fills.map(f=>f.type==='SOLID'?'#'+[f.color.r,f.color.g,f.color.b].map(v=>Math.round(v*255).toString(16).padStart(2,'0')).join(''):f.type))}`;
  }
  let out = s + '\n';
  for (const c of node.children || []) out += dump(c, depth+1);
  return out;
}
