  // center action
  const cir=frame('cx',172,4,46,46); cir.cornerRadius=23; cir.fills=[{type:'SOLID',color:brand}]; tb.appendChild(cir);
  const ci=inst(centerKey); ci.x=8; ci.y=8; if(ci){ci.fills=ci.children.map? null:null; ci.children.forEach? ci.children.forEach(ch=>{if(ch&&ch.fills&&ch.fills[0]&&ch.fills[0].type==='SOLID')ch.fills=[{type:'SOLID',color:{r:1,g:1,b:1}}]}):null;} cir.appendChild(ci);
  const cl=txt('Support','Nunito','Regular',9,{r:1,g:1,b:1}); cl.x=0; cl.y=50;cl.resize(46,12);cl.textAlignHorizontal='CENTER'; cir.appendChild(cl);
  // four items
  let x=0;
  for(const [name,key] of items){
    const it=frame(name,96,76); it.x=x; tb.appendChild(it);
    const ic=inst(key); ic.x=38; ic.y=8; it.appendChild(ic);
    const col = name===cur ? brand : {r:0.6,g:0.62,b:0.6};
    if(ic&&ic.children) ic.children.forEach(ch=>{if(ch&&ch.fills&&ch.fills[0]&&ch.fills[0].type==='SOLID')ch.fills=[{type:'SOLID',color:col}]});
    const lb=txt(name,'Nunito','Bold',11,col); lb.x=0; lb.y=48; lb.resize(96,14); lb.textAlignHorizontal='CENTER'; it.appendChild(lb);
