function brief(n){
  let s = n.type+' '+n.name+'('+n.id+')';
  if(n.type==='TEXT'){try{s+=' "'+n.characters+'"'}catch(e){}}
  return s;
}
function walk(n,d,arr){
  if(d>6) return;
  arr.push('  '.repeat(d)+brief(n));
  for(const c of n.children||[]) walk(c,d+1,arr);
}
