// Inspect media symbol internals
function walk(n,d,arr){
  if(d>3) return;
  let s='  '.repeat(d)+n.type+' '+n.name+'('+n.id+')';
  if(n.type==='TEXT'){ try{s+=' "'+n.characters+'"'}catch(e){} }
  if(n.fills){ 
    s+=' fill='+n.fills.map(f=> f.type==='SOLID'?'#'+[f.color.r,f.color.g,f.color.b].map(v=>Math.round(v*255).toString(16).padStart(2,'0')).join(''):f.type).join(',');
  }
  arr.push(s);
  for(const c of n.children||[]) walk(c,d+1,arr);
}
