function walk(n,d,arr){
  if(d>3)return;
  let s='  '.repeat(d)+n.type+' '+n.name+'('+n.id+') w='+Math.round(n.width)+' h='+Math.round(n.height);
  if(n.type==='TEXT'){try{s+=' "'+n.characters+'"'}catch(e){}}
  arr.push(s); for(const c of n.children||[])walk(c,d+1,arr);
}
