function hx(c){ return {type:'SOLID', color:{r:parseInt(c.slice(1,3),16)/255, g:parseInt(c.slice(3,5),16)/255, b:parseInt(c.slice(5,7),16)/255}}; }
function rect(parent,x,y,w,h,fill,radius){ const r=figma.createRectangle(); r.resize(w,h); r.x=x; r.y=y; r.fills=[hx(fill)]; if(radius) r.cornerRadius=radius; parent.appendChild(r); return r; }
function round(rad, opts){ const r=figma.createRectangle(); r.resize(rad.w, rad.h); r.x=rad.x; r.y=rad.y; r.fills=[hx(rad.fill)]; r.cornerRadius=rad.r; if(rad.opacity!=null) r.opacity=rad.opacity; parentNode(rad.p).appendChild(r); return r; }
function parentNode(p){ return p; }
function text(parent,str,x,y,size,fill,font,style,width,align){ const t=figma.createText(); t.characters=str; t.x=x; t.y=y; t.fontSize=size; t.fills=[hx(fill)]; t.fontName={family:font,style:style}; t.textAutoResize='HEIGHT'; if(width) t.resize(width??0, t.height); if(align) t.textAlignHorizontal=align; parent.appendChild(t); return t; }
function inst(compId){ const c=figma.getNodeById(compId); if(!c){ console.log('no '+compId); return null;} const i=c.createInstance(); return i; }
function put(parent,child,x,y){ child.x=x; child.y=y; parent.appendChild(child); return child; }

