function text(parent, x, y, str, font, size, color, align){
  const t = figma.createText();
  t.fontName = font; t.fontSize = size;
  t.characters = str; t.x = x; t.y = y;
  t.fills = [{type:'SOLID', color: color||C.ink}];
  if(align==='center') t.textAlignHorizontal = 'CENTER';
  if(align==='right') t.textAlignHorizontal = 'RIGHT';
  parent.appendChild(t);
  return t;
}
function inst(parent, compId, x, y){
  const c = figma.getNodeById(compId);
  const i = c.createInstance();
  i.x = x; i.y = y;
  parent.appendChild(i);
  return i;
}
function rect(parent, x, y, w, h, color, radius){
  const r = figma.createRectangle();
  r.x=x; r.y=y; r.resize(w,h);
  r.fills = color ? [{type:'SOLID', color}] : [];
  if(radius) r.cornerRadius = radius;
  parent.appendChild(r);
  return r;
}
function wrap(parent, x, y, w){
  parent.x=x; parent.y=y; parent.resize(w, parent.height);
  return parent;
}

